// HTML do logotipo (SVG inline). classe: classes extras; { variante: 'cor' | 'claro' | 'mono' | 'globo', titulo, simples }
const logo = (classe = '', opcoes = {}) => LOGO.svg(classe, opcoes);

// Entrada do logotipo na tela inicial (guia §8.2): devolve a timeline GSAP (pulável com tl.progress(1)).
function animarLogo(svg, { brilhoACada = 8 } = {}) {
  if (!svg || typeof gsap === 'undefined') return null;
  const reduzido = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const letras = [...svg.querySelectorAll('.logo-letra')], irada = svg.querySelector('.logo-irada'), brilho = svg.querySelector('.logo-brilho');
  const tl = gsap.timeline();
  if (reduzido) { tl.set(letras, { opacity: 1, y: 0 }); return tl; }
  gsap.set(letras, { transformOrigin: '50% 100%' });
  letras.forEach((l, i) => {
    const t = i * .05 + (i >= 9 ? .18 : 0);
    tl.fromTo(l, { y: -420, opacity: 0 }, { y: 0, opacity: 1, duration: .26, ease: 'power2.in' }, t)
      .fromTo(l, { scaleY: .82, scaleX: 1.1 }, { scaleY: 1, scaleX: 1, duration: .2, ease: 'back.out(3)' }, t + .26);
  });
  // "IRADA" bate por último: tremidinha + 8 tijolinhos de poeira
  const batida = tl.duration() - .16;
  if (irada) {
    tl.to(irada, { keyframes: [{ x: -9, duration: .04 }, { x: 8, duration: .04 }, { x: -5, duration: .04 }, { x: 0, duration: .05 }] }, batida);
    tl.add(() => poeiraLogo(svg), batida);
  }
  if (brilho && brilhoACada) {
    const raio = brilho.querySelector('.logo-raio');
    tl.set(brilho, { opacity: 1 }, '+=.3')
      .fromTo(raio, { x: 0 }, { x: 2100, duration: .6, ease: 'power1.inOut', repeat: -1, repeatDelay: brilhoACada - .6 });
  }
  return tl;
}
function poeiraLogo(svg) {
  const NS = 'http://www.w3.org/2000/svg', g = document.createElementNS(NS, 'g');
  svg.appendChild(g);
  const cores = ['#FFD21F', '#FFFFFF', '#FFE97E', '#FFD21F'];
  for (let i = 0; i < 8; i++) {
    const r = document.createElementNS(NS, 'rect'), lado = i < 4 ? -1 : 1, x0 = 800 + lado * (380 + (i % 4) * 30);
    Object.entries({ x: -16, y: -11, width: 32, height: 22, rx: 6, fill: cores[i % 4], stroke: '#1A1433', 'stroke-width': 6 }).forEach(([k, v]) => r.setAttribute(k, v));
    g.appendChild(r);
    gsap.fromTo(r, { x: x0, y: 735, rotation: 0, opacity: 1 }, { x: x0 + lado * (60 + Math.random() * 90), y: 735 - 60 - Math.random() * 90, rotation: lado * (90 + Math.random() * 200), opacity: 0, duration: .7 + Math.random() * .25, ease: 'power2.out', onComplete: () => r.remove() });
  }
  setTimeout(() => g.remove(), 1200);
}

